-- migrate:up

-- Demo plots p1213-001..015 take real geometry: each gets its own Miyagi 区画漁業権 zone licensed for
-- hanging shellfish culture (貝類等垂下式養殖業), chosen by minimum total distance from its old synthetic
-- point (Hungarian assignment; 0-1.84 km, 3 of 15 points were already inside their zone). Polygons are
-- copied from pipeline/data/ref/fishery-rights/miyagi-kukaku-2023.geojson so this migration runs on a
-- database where the fishery-right plots were never loaded. The zone's own row (04-ku-*) is separate;
-- source_url names it. sea_area_id stays 'karakuwa-east': it is the on-chain zone these plots belong to,
-- even where the licence polygon lies in the traced kesennuma-bay area.
-- The archive trigger keeps each 50 m disc in geo.plots_history and resets valid_from.
-- Only rows still 'synthetic' are touched.

UPDATE geo.plots p
SET geom = ST_Multi(ST_GeomFromText(d.wkt, 4326)),
    origin = 'fishery_right',
    operation = 'longline',
    source_url = 'https://www.jfa.maff.go.jp/j/enoki/attach/pdf/gyogyouken_jouhou3-434.pdf#' || d.right_no || ' (zone ' || d.zone || ')',
    source_sha256 = '20b6e4e6033d7fe698245861b0c88cefcf649d64fea25be31f7edbdef9fa5fc1',
    valid_to = '2028-08-31'
